        "avifSrcset": "/media/blog/en/what-is-spendist/cover/cover-320.avif 320w, /media/blog/en/what-is-spendist/cover/cover-480.avif 480w, /media/blog/en/what-is-spendist/cover/cover-768.avif 768w, /media/blog/en/what-is-spendist/cover/cover-1024.avif 1024w, /media/blog/en/what-is-spendist/cover/cover-1200.avif 1200w",
        "webpSrcset": "/media/blog/en/what-is-spendist/cover/cover-320.webp 320w, /media/blog/en/what-is-spendist/cover/cover-480.webp 480w, /media/blog/en/what-is-spendist/cover/cover-768.webp 768w, /media/blog/en/what-is-spendist/cover/cover-1024.webp 1024w, /media/blog/en/what-is-spendist/cover/cover-1200.webp 1200w"
